#!/usr/bin/env python3
"""
og_card.py  -  Self-contained generator for J. Ryan Lamare's Open Graph card.

Rebuilds the 1200x630 OG card from code. Text is rendered live with the same
two typefaces the website uses (Archivo + IBM Plex Mono), matched to the
original card's exact sizes, weights, widths, tracking and colours. The RL
logo, the red name-rule, and the seven-icon row are the ORIGINAL artwork,
embedded below as base64 PNGs, so they stay pixel-identical.

Edit the CONFIG block, then run:  python3 og_card.py   ->   og-card.png

Fonts are downloaded from the Google Fonts GitHub mirror on first run and
cached next to this script (needs internet once).
"""
import os, sys, base64, io, urllib.request
from PIL import Image, ImageFont, ImageDraw

# ----------------------------- CONFIG -----------------------------
NAME      = "J. RYAN LAMARE"
KICKER    = "LONDON SCHOOL OF ECONOMICS"
ROLE_1    = "Professor of Employment Relations"
ROLE_2    = "and Human Resource Management"
EMAIL     = "r.lamare@lse.ac.uk"
URL       = "ryanlamare.com"          # <-- updated domain
OUTPUT    = "og-card.png"
# ------------------------------------------------------------------

# Canvas + palette (sampled from the original card)
W, H   = 1200, 630
BG     = (245, 241, 230)   # #f5f1e6
INK    = (33, 26, 24)      # #211a18
RED    = (224, 17, 43)     # #e0112b

# Element geometry (centre x is the canvas centre; y is the vertical centre
# of each element, measured from the original card).
CX        = W // 2
LOGO_XY   = (568, 52)
KICKER_CY = 143
NAME_CY   = 227
RULE_XY   = (528, 268)
ROLE1_CY  = 327
ROLE2_CY  = 368
CONTACT_CY= 432
ICONS_XY  = (300, 492)

# Fonts (Google Fonts mirror)
FONTS = {
    "Archivo[wdth,wght].ttf":
        "https://raw.githubusercontent.com/google/fonts/main/ofl/archivo/Archivo%5Bwdth%2Cwght%5D.ttf",
    "IBMPlexMono-Regular.ttf":
        "https://raw.githubusercontent.com/google/fonts/main/ofl/ibmplexmono/IBMPlexMono-Regular.ttf",
}

def font_path(fn):
    here = os.path.dirname(os.path.abspath(__file__))
    p = os.path.join(here, fn)
    if not os.path.exists(p):
        print("downloading", fn, "...")
        urllib.request.urlretrieve(FONTS[fn], p)
    return p

def archivo(size, weight, width=100):
    f = ImageFont.truetype(font_path("Archivo[wdth,wght].ttf"), size)
    f.set_variation_by_axes([weight, width])   # axis order: [Weight, Width]
    return f

def plexmono(size):
    return ImageFont.truetype(font_path("IBMPlexMono-Regular.ttf"), size)

def tracked(text, font, tracking=0.0, fill=INK):
    """Render text with per-glyph tracking; return a tightly-cropped RGBA."""
    widths = [font.getlength(c) for c in text]
    asc, desc = font.getmetrics()
    canvas = Image.new("RGBA",
                       (int(sum(widths) + abs(tracking) * len(text) + 80),
                        asc + desc + 60), (0, 0, 0, 0))
    d = ImageDraw.Draw(canvas)
    x = 40
    for c, w in zip(text, widths):
        d.text((x, 30), c, font=font, fill=fill)
        x += w + tracking
    return canvas.crop(canvas.getbbox())

def paste_centered(base, layer, cx, cy):
    base.alpha_composite(layer, (int(cx - layer.width / 2),
                                 int(cy - layer.height / 2)))

def art(data):
    return Image.open(io.BytesIO(base64.b64decode(data))).convert("RGBA")

def main():
    img = Image.new("RGBA", (W, H), BG + (255,))

    # original artwork (embedded)
    img.alpha_composite(art(LOGO_B64),  LOGO_XY)
    img.alpha_composite(art(RULE_B64),  RULE_XY)
    img.alpha_composite(art(ICONS_B64), ICONS_XY)

    # live text
    paste_centered(img, tracked(KICKER, archivo(14, 700), 4.5, RED),  CX, KICKER_CY)
    paste_centered(img, tracked(NAME,   archivo(68, 900), 0.0, INK),  CX, NAME_CY)
    paste_centered(img, tracked(ROLE_1, archivo(30, 500), 0.0, INK),  CX, ROLE1_CY)
    paste_centered(img, tracked(ROLE_2, archivo(30, 500), 0.0, INK),  CX, ROLE2_CY)

    contact = EMAIL + "     \u00b7     " + URL
    paste_centered(img, tracked(contact, plexmono(18), 0.0, INK), CX, CONTACT_CY)

    img.convert("RGB").save(OUTPUT)
    print("wrote", OUTPUT)

# ------------------- embedded original artwork -------------------
LOGO_B64 = ""
RULE_B64 = ""
ICONS_B64 = ""

if __name__ == "__main__":
    main()
